{"path": "units/chain/stage1.py", "content": "import csv


def parse_orders(csv_path):
    rows = []
    with open(csv_path, newline="") as f:
        for row in csv.DictReader(f):
            rows.append(
                {"id": int(row["id"]), "qty": int(row["qty"]), "price": int(row["price"])}
            )
    return rows
"}

{"path": "units/chain/stage3.py", "content": "def total_by_price(rows):
    totals = {}
    for r in rows:
        totals[r["price"]] = totals.get(r["price"], 0) + r["qty"]
    return totals
"}
